/* ==========================================================================
   Clearmind Therapy — Design System
   ========================================================================== */

:root {
  --slate: #1A2332;
  --cloud: #F5F7FA;
  --sage: #4AAE8C;
  --sage-deep: #3A9478;
  --mist: #E8EEF4;
  --stone: #6B7A8F;
  --dew: #D6F0E8;
  --white: #FFFFFF;
  --coral: #E8715A;
  --coral-tint: #FAE8E5;
  --stone-on-dark: #B8C3D0;

  --font-heading: 'Manrope', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-body: 'Source Sans 3', system-ui, -apple-system, sans-serif;
  --font-accent: 'DM Sans', system-ui, -apple-system, sans-serif;

  --shadow-sm: 0 2px 12px rgba(26, 35, 50, 0.06);
  --shadow-md: 0 2px 16px rgba(26, 35, 50, 0.07);
  --shadow-lg: 0 4px 24px rgba(26, 35, 50, 0.08);
  --shadow-hover: 0 6px 24px rgba(26, 35, 50, 0.12);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-2xl: 24px;

  --container: 1200px;
  --container-narrow: 1120px;
}

/* ==========================================================================
   Reset & base
   ========================================================================== */
*,
*::before,
*::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  font-weight: 400;
  font-size: 16px;
  line-height: 1.7;
  color: var(--slate);
  background-color: var(--cloud);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--slate);
  margin: 0;
}

p { margin: 0; }

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

img, svg { display: block; max-width: 100%; }

ul { list-style: none; padding: 0; margin: 0; }

/* ==========================================================================
   Layout helpers
   ========================================================================== */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

.container--narrow { max-width: var(--container-narrow); }

.section { padding: 100px 0; }
.section--compact { padding: 80px 0; }
.section--header { padding: 96px 0 72px; }

@media (max-width: 1024px) {
  .section { padding: 64px 0; }
  .section--compact { padding: 56px 0; }
  .section--header { padding: 64px 0 48px; }
}

@media (max-width: 640px) {
  .section { padding: 48px 0; }
  .section--compact { padding: 40px 0; }
  .section--header { padding: 48px 0 32px; }
  .container { padding: 0 20px; }
}

/* ==========================================================================
   Typography
   ========================================================================== */
.eyebrow {
  display: inline-block;
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: var(--sage);
  margin-bottom: 12px;
}

.eyebrow--stone { color: var(--stone); }

.headline-display {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(36px, 5vw, 60px);
  letter-spacing: -0.03em;
  line-height: 1.1;
  color: var(--slate);
}

.headline-page {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(32px, 4.4vw, 52px);
  letter-spacing: -0.03em;
  line-height: 1.15;
  color: var(--slate);
}

.headline-section {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(28px, 3.6vw, 44px);
  letter-spacing: -0.025em;
  line-height: 1.15;
}

.headline-medium {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(24px, 3vw, 36px);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.subheadline {
  font-family: var(--font-body);
  font-weight: 400;
  font-size: 18px;
  line-height: 1.7;
  color: var(--stone);
  margin-top: 16px;
}

.section-header { margin-bottom: 40px; }
.section-header--center { text-align: center; }
.section-header--center .subheadline { max-width: 580px; margin-left: auto; margin-right: auto; }

/* ==========================================================================
   Buttons
   ========================================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.01em;
  padding: 14px 28px;
  border-radius: 10px;
  border: 1.5px solid transparent;
  transition: background-color 200ms ease, border-color 200ms ease, color 200ms ease, transform 200ms ease, box-shadow 200ms ease;
  text-align: center;
  white-space: nowrap;
}

.btn-primary {
  background: var(--sage);
  color: var(--white);
  border-color: var(--sage);
}
.btn-primary:hover {
  background: var(--sage-deep);
  border-color: var(--sage-deep);
}

.btn-secondary {
  background: transparent;
  color: var(--slate);
  border-color: var(--slate);
}
.btn-secondary:hover { background: var(--mist); }

.btn-on-dark-secondary {
  background: transparent;
  color: var(--white);
  border-color: var(--white);
}
.btn-on-dark-secondary:hover { background: rgba(255,255,255,0.10); }

.btn-outline-sage {
  background: var(--white);
  color: var(--sage);
  border-color: var(--sage);
}
.btn-outline-sage:hover {
  background: var(--sage);
  color: var(--white);
}

.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 32px;
}

@media (max-width: 640px) {
  .btn { width: 100%; }
  .btn-row { flex-direction: column; gap: 12px; }
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 15px;
  color: var(--sage);
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
  transition: color 200ms ease, border-color 200ms ease;
}
.text-link:hover {
  color: var(--slate);
  border-bottom-color: currentColor;
}

/* ==========================================================================
   Navigation
   ========================================================================== */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--slate);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

.site-nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 18px;
  letter-spacing: -0.02em;
  color: var(--white);
}

.brand__mark {
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 14px;
  color: var(--stone-on-dark);
  transition: color 200ms ease;
  position: relative;
  padding: 6px 0;
}

.nav-links a:hover { color: var(--white); }

.nav-links a.is-active {
  color: var(--white);
}
.nav-links a.is-active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 2px;
  background: var(--sage);
  border-radius: 2px;
}

.nav-cta {
  background: var(--sage);
  color: var(--white);
  padding: 10px 18px;
  border-radius: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 14px;
  transition: background-color 200ms ease;
}
.nav-cta:hover { background: var(--sage-deep); }

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: transparent;
  color: var(--white);
}
.nav-toggle svg { width: 20px; height: 20px; margin: 0 auto; }

@media (max-width: 880px) {
  .nav-links {
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    flex-direction: column;
    gap: 0;
    background: var(--slate);
    padding: 16px 24px 24px;
    border-bottom: 1px solid rgba(255,255,255,0.05);
    display: none;
  }
  .nav-links.is-open { display: flex; }
  .nav-links a { padding: 12px 0; width: 100%; border-bottom: 1px solid rgba(255,255,255,0.05); }
  .nav-links a.is-active::after { display: none; }
  .nav-toggle { display: inline-flex; align-items: center; justify-content: center; }
  .nav-cta { display: none; }
}

/* ==========================================================================
   Footer
   ========================================================================== */
.site-footer {
  background: var(--slate);
  color: var(--stone-on-dark);
  padding: 64px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  gap: 48px;
}

.footer-col h4 {
  color: var(--white);
  font-family: var(--font-accent);
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  margin-bottom: 16px;
}

.footer-col p {
  font-size: 14px;
  line-height: 1.7;
  margin-bottom: 12px;
}

.footer-col li { margin-bottom: 10px; }
.footer-col li a {
  color: var(--stone-on-dark);
  font-size: 14px;
  transition: color 200ms ease;
}
.footer-col li a:hover { color: var(--white); }

.footer-bottom {
  margin-top: 48px;
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.08);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
}

@media (max-width: 880px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}
@media (max-width: 540px) {
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
}

/* ==========================================================================
   Hero (home)
   ========================================================================== */
.hero {
  background: var(--cloud);
  padding: 80px 0 100px;
}

.hero__grid {
  display: grid;
  grid-template-columns: 55% 45%;
  align-items: center;
  gap: 48px;
}

.hero__copy .headline-display { margin-top: 0; }
.hero__copy .subheadline { margin-top: 20px; max-width: 480px; }

.hero__visual {
  background: var(--white);
  border-radius: var(--radius-2xl);
  box-shadow: 0 4px 24px rgba(26,35,50,0.07);
  padding: 28px;
  aspect-ratio: 4 / 3.6;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero__visual svg { width: 100%; height: 100%; }

@media (max-width: 1024px) {
  .hero__grid { grid-template-columns: 1fr; }
  .hero__visual { max-height: 400px; aspect-ratio: 16/10; }
}

@media (max-width: 640px) {
  .hero { padding: 56px 0 64px; }
  .hero__visual { padding: 16px; aspect-ratio: 16/9; }
}

/* ==========================================================================
   Stats section
   ========================================================================== */
.stats {
  background: var(--mist);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 40px;
}

.stat-tile {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  box-shadow: var(--shadow-sm);
  min-height: 140px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.stat-tile--accent { background: var(--dew); }

.stat-tile__value {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(32px, 3.5vw, 44px);
  color: var(--sage);
  letter-spacing: -0.02em;
  line-height: 1;
}

.stat-tile__label {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.5;
  color: var(--stone);
  margin-top: 12px;
}

@media (max-width: 880px) {
