}
@media (max-width: 480px) {
  .stats-grid { grid-template-columns: 1fr; }
  .stat-tile { padding: 24px; }
}

/* ==========================================================================
   Feature grid (home)
   ========================================================================== */
.feature-bento {
  display: grid;
  grid-template-columns: 58% 42%;
  grid-template-rows: auto auto;
  gap: 16px;
  margin-top: 40px;
}

.feature-bento .tile { padding: 32px; border-radius: var(--radius-lg); box-shadow: var(--shadow-sm); position: relative; }
.feature-bento .tile h3 { font-size: 20px; margin-bottom: 10px; }
.feature-bento .tile p { font-size: 15px; color: var(--stone); line-height: 1.7; }

.feature-bento .tile--white { background: var(--white); }
.feature-bento .tile--dew { background: var(--dew); }
.feature-bento .tile--mist { background: var(--mist); }

.feature-bento .tile--dark {
  background: var(--slate);
  grid-row: span 2;
  color: var(--white);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
}
.feature-bento .tile--dark h3 { color: var(--white); }
.feature-bento .tile--dark p { color: rgba(255,255,255,0.78); }

.tile--dark .deco-shape {
  position: absolute;
  right: -80px;
  bottom: -80px;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: var(--sage);
  opacity: 0.14;
  pointer-events: none;
}

.tile-icon {
  width: 36px;
  height: 36px;
  background: var(--dew);
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--sage);
}

.tile--dark .tile-icon { background: rgba(74,174,140,0.18); color: var(--sage); }

@media (max-width: 880px) {
  .feature-bento { grid-template-columns: 1fr; }
  .feature-bento .tile--dark { grid-row: auto; }
}

/* ==========================================================================
   Testimonials
   ========================================================================== */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 40px;
}

.testimonial {
  position: relative;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px;
  box-shadow: var(--shadow-lg);
  min-height: 260px;
  display: flex;
  flex-direction: column;
}

.testimonial--accent { background: var(--dew); box-shadow: none; }

.testimonial__quote-mark {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 56px;
  line-height: 1;
  color: var(--sage);
  opacity: 0.32;
  margin-bottom: 8px;
}

.testimonial__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 18px;
  color: var(--slate);
  margin-bottom: 12px;
}

.testimonial__body {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--stone);
  line-height: 1.7;
  flex-grow: 1;
}

.testimonial__attribution {
  margin-top: 24px;
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--stone);
}

.testimonial__dot {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--coral);
}

@media (max-width: 1024px) {
  .testimonials-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .testimonials-grid { grid-template-columns: 1fr; }
}

/* ==========================================================================
   Closing CTA — slate
   ========================================================================== */
.cta-slate {
  background: var(--slate);
  color: var(--white);
  position: relative;
  overflow: hidden;
}

.cta-slate__pattern {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.55;
}

.cta-slate__inner {
  position: relative;
  text-align: center;
  max-width: 720px;
  margin: 0 auto;
}

.cta-slate h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(28px, 4vw, 48px);
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--white);
}

.cta-slate p.subheadline {
  color: rgba(255, 255, 255, 0.72);
  max-width: 480px;
  margin: 20px auto 0;
}

.cta-slate .btn-row {
  justify-content: center;
}

/* ==========================================================================
   Page header (services / practitioners / resources / contact)
   ========================================================================== */
.page-header {
  background: var(--cloud);
}
.page-header--mist { background: var(--mist); }

.page-header__inner {
  text-align: center;
  max-width: 720px;
  margin: 0 auto;
}

.page-header__inner .subheadline { max-width: 600px; margin-left: auto; margin-right: auto; }

.page-header__rule {
  width: 48px;
  height: 1px;
  background: var(--mist);
  margin: 0 auto 20px;
}

.page-header__split {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 40px;
}

.deco-cluster {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  width: 220px;
}
.deco-cluster span {
  display: block;
  height: 56px;
  border-radius: 14px;
  background: var(--dew);
}
.deco-cluster span:nth-child(1) { background: var(--white); transform: rotate(-3deg); }
.deco-cluster span:nth-child(2) { transform: rotate(4deg); }
.deco-cluster span:nth-child(3) { transform: rotate(2deg); height: 70px; }
.deco-cluster span:nth-child(4) { background: var(--white); transform: rotate(-5deg); height: 64px; }

@media (max-width: 1024px) {
  .deco-cluster { display: none; }
  .page-header__split { grid-template-columns: 1fr; text-align: center; }
}

/* ==========================================================================
   Services — item grid
   ========================================================================== */
.services-section {
  background: var(--white);
}

.service-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 40px;
}

.service-card {
  background: var(--mist);
  border-radius: var(--radius-xl);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  border: 1.5px solid transparent;
  transition: box-shadow 200ms ease, border-color 200ms ease, transform 200ms ease;
  display: flex;
  flex-direction: column;
}
.service-card:hover {
  box-shadow: var(--shadow-hover);
  border-color: var(--sage);
  transform: translateY(-2px);
}

.service-card__icon {
  width: 36px;
  height: 36px;
  margin-bottom: 16px;
  color: var(--sage);
}
.service-card__icon svg { width: 100%; height: 100%; }

.service-card h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 20px;
  color: var(--slate);
  margin-bottom: 10px;
}

.service-card p {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--stone);
  line-height: 1.65;
  margin-bottom: 16px;
  flex-grow: 1;
}

.pill-row { display: flex; gap: 8px; flex-wrap: wrap; }
.pill {
  background: var(--dew);
  color: var(--sage);
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  border-radius: 20px;
}

.service-grid + .center-cta { text-align: center; margin-top: 40px; }

@media (max-width: 1024px) {
  .service-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .service-grid { grid-template-columns: 1fr; }
}

/* ==========================================================================
   Comparison panels
   ========================================================================== */
.comparison-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 40px;
  align-items: stretch;
}

.compare-panel {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  border-left: 3px solid var(--sage);
  display: flex;
  flex-direction: column;
}
.compare-panel--accent { background: var(--dew); }

.compare-panel h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 22px;
  color: var(--slate);
  margin-bottom: 12px;
}

.compare-panel p {
  font-size: 16px;
  color: var(--stone);
  line-height: 1.7;
  margin-bottom: 24px;
  flex-grow: 1;
}

.compare-meta {
  border-top: 1px solid var(--mist);
  padding-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.compare-panel--accent .compare-meta { border-top-color: rgba(26,35,50,0.06); }

.compare-meta__row {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 12px;
  align-items: center;
}
.compare-meta__label {
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--stone);
}
.compare-meta__value {
  font-size: 15px;
  color: var(--slate);
}

@media (max-width: 880px) {
  .comparison-grid { grid-template-columns: 1fr; }
}

/* ==========================================================================
   FAQ
   ========================================================================== */
.faq-section {
  background: var(--white);
}

.faq-list {
  max-width: 760px;
  margin-top: 36px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.faq-list--center { margin-left: auto; margin-right: auto; }

.faq-item {
  background: var(--cloud);
  border-radius: 14px;
  padding: 20px 24px;
  border: 1.5px solid transparent;
  transition: background-color 200ms ease, border-color 200ms ease;
}

.faq-item[open] {
  background: var(--white);
  border-color: var(--sage);
  box-shadow: var(--shadow-sm);
}

.faq-item summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  cursor: pointer;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  color: var(--slate);
  list-style: none;
}
.faq-item summary::-webkit-details-marker { display: none; }

.faq-chevron {
  width: 18px;
  height: 18px;
  color: var(--stone);
  flex: 0 0 auto;
  transition: transform 200ms ease, color 200ms ease;
}
.faq-item[open] .faq-chevron {
  transform: rotate(180deg);
  color: var(--sage);
}

.faq-answer {
  margin-top: 12px;
  padding-top: 12px;
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--stone);
  line-height: 1.7;
  border-top: 1px solid var(--mist);
}

/* CTA-tinted FAQ (Contact page variant) */
.faq-list--cards .faq-item {
  background: var(--white);
  border: 1px solid var(--mist);
  border-radius: 12px;
}
.faq-list--cards .faq-item[open] {
  background: var(--dew);
  border-color: var(--sage);
}
.faq-list--cards .faq-item summary { font-weight: 600; font-size: 16px; }
.faq-list--cards .faq-chevron::before {
  content: "+";
  font-size: 20px;
  font-weight: 700;
  color: var(--sage);
  display: block;
  line-height: 1;
}
.faq-list--cards .faq-chevron { background: none; }
.faq-list--cards .faq-chevron svg { display: none; }
.faq-list--cards .faq-item[open] .faq-chevron::before { content: "×"; }
.faq-list--cards .faq-answer { border-top: 1px solid rgba(26,35,50,0.06); }

/* ==========================================================================
   Closing CTA — Dew
   ========================================================================== */
.cta-dew {
  background: var(--dew);
  padding: 96px 0;
}

.cta-dew__grid {
  display: grid;
  grid-template-columns: 60% 40%;
  align-items: center;
  gap: 48px;
}

.cta-dew__copy h2 { color: var(--slate); max-width: 480px; }
.cta-dew__copy .subheadline { max-width: 420px; }

.cta-dew__visual { display: flex; justify-content: flex-end; }
.cta-dew__visual svg { max-width: 340px; width: 100%; height: auto; }

@media (max-width: 1024px) {
  .cta-dew__grid { grid-template-columns: 1fr; }
  .cta-dew__visual { display: none; }
  .cta-dew { padding: 64px 0; }
}

/* CTA — gradient */
.cta-gradient {
  background: linear-gradient(180deg, var(--dew) 0%, var(--cloud) 100%);
  text-align: center;
}

.cta-gradient .reassure-row {
  margin-top: 28px;
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--stone);
}

/* ==========================================================================
   Practitioners grid
   ========================================================================== */
.practitioner-section { background: var(--cloud); }

.practitioner-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 40px;
}

/* asymmetric desktop layout (per design plan) */
.practitioner-grid > .practitioner-card:nth-child(1) { grid-column: span 2; }
.practitioner-grid > .practitioner-card:nth-child(6) { grid-column: span 2; }

.practitioner-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}

.practitioner-card__head {
  display: flex;
  gap: 16px;
  align-items: center;
  margin-bottom: 16px;
}

.avatar-tile {
  width: 80px;
  height: 80px;
  border-radius: 18px;
  background: var(--dew);
  flex: 0 0 auto;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.avatar-tile svg { width: 100%; height: 100%; }

.practitioner-card__name {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 18px;
  color: var(--slate);
  margin-bottom: 4px;
}

.practitioner-card__specialty {
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: var(--sage);
}

.practitioner-card__desc {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--stone);
  line-height: 1.65;
  flex-grow: 1;
}

.practitioner-card__divider {
  height: 1px;
  background: var(--mist);
  margin: 16px 0 12px;
}

.meta-pills { display: flex; flex-wrap: wrap; gap: 6px; }
.meta-pill {
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 6px 10px;
  border-radius: 6px;
  background: var(--mist);
  color: var(--stone);
}
.meta-pill--accept { background: var(--dew); color: var(--sage); }
.meta-pill--limited { background: var(--coral-tint); color: var(--coral); }

@media (max-width: 1024px) {
  .practitioner-grid { grid-template-columns: repeat(2, 1fr); }
  .practitioner-grid > .practitioner-card:nth-child(1),
  .practitioner-grid > .practitioner-card:nth-child(6) { grid-column: auto; }
}
@media (max-width: 640px) {
  .practitioner-grid { grid-template-columns: 1fr; }
}

/* ==========================================================================
   Story block (practitioners — slate)
   ========================================================================== */
.story-slate {
  background: var(--slate);
  color: var(--white);
}

.story-slate__grid {
  display: grid;
  grid-template-columns: 60% 40%;
  gap: 48px;
  align-items: center;
}

.story-slate h2 { color: var(--white); }
.story-slate p {
  margin-top: 24px;
