}

@media (max-width: 1024px) {
  .story-slate__grid { grid-template-columns: 1fr; }
  .story-slate__visual { display: none; }
}

/* ==========================================================================
   Story block — mist (resources)
   ========================================================================== */
.story-mist {
  background: var(--mist);
}

.story-mist__inner {
  max-width: 760px;
  margin: 0 auto;
}

.story-mist__body {
  position: relative;
  padding-left: 24px;
  margin-top: 20px;
  font-size: 17px;
  line-height: 1.75;
