}
@media (max-width: 640px) {
  .article-grid { grid-template-columns: 1fr; }
  .article-card--hero { grid-column: auto; }
}

/* ==========================================================================
   Resources — feature library grid
   ========================================================================== */
.library-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-top: 40px;
}

.library-tile {
  background: var(--dew);
  border-radius: 28px;
  padding: 32px;
  display: flex;
  flex-direction: column;
  min-height: 240px;
  transition: background-color 200ms ease, box-shadow 200ms ease;
}
.library-tile:hover {
  background: var(--mist);
  box-shadow: 0 4px 16px rgba(26,35,50,0.10);
}

.library-tile--alert {
  background: var(--white);
  border-left: 3px solid var(--coral);
}
.library-tile--alert:hover { background: #FDF2F0; }
.library-tile--alert .library-tile__icon { color: var(--coral); }

.library-tile__icon {
  width: 40px;
  height: 40px;
  color: var(--sage);
  margin-bottom: 16px;
}

.library-tile h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 20px;
  color: var(--slate);
  margin-bottom: 8px;
}

.library-tile p {
  font-size: 15px;
  color: var(--stone);
  line-height: 1.65;
  flex-grow: 1;
}

.library-tile__link {
  margin-top: 16px;
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 13px;
  color: var(--sage);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

@media (max-width: 640px) {
  .library-grid { grid-template-columns: 1fr; }
}

/* ==========================================================================
   Contact form
   ========================================================================== */
.contact-form-section { background: var(--white); padding: 80px 0; }

.contact-form-grid {
  display: grid;
  grid-template-columns: 60% 40%;
  gap: 48px;
  align-items: start;
}

.contact-form .eyebrow { color: var(--stone); }
.contact-form h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 30px;
  color: var(--slate);
  margin-top: 8px;
  letter-spacing: -0.02em;
}
.contact-form > p {
  margin-top: 16px;
  font-size: 16px;
  color: var(--stone);
  line-height: 1.65;
}

.field-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-top: 28px;
}
.field-grid .field--full { grid-column: span 2; }

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field label {
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--stone);
}
.field label .required-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  background: var(--sage);
  border-radius: 50%;
  margin-left: 6px;
  vertical-align: middle;
}
.field label .field-hint {
  display: block;
  font-family: var(--font-body);
  font-weight: 400;
  font-size: 13px;
  text-transform: none;
  letter-spacing: normal;
  color: var(--stone);
  margin-top: 4px;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--slate);
  border: 1px solid var(--mist);
  border-radius: 8px;
  padding: 12px 14px;
  background: var(--white);
  transition: border-color 200ms ease, box-shadow 200ms ease;
}
.field textarea { min-height: 120px; resize: vertical; }
.field select { appearance: none; background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%236B7A8F' stroke-width='2'><polyline points='6 9 12 15 18 9'/></svg>"); background-repeat: no-repeat; background-position: right 14px center; background-size: 16px; padding-right: 40px; }

.field input::placeholder,
.field textarea::placeholder { color: var(--stone); opacity: 0.6; }

.field input:focus,
.field select:focus,
.field textarea:focus {
  outline: none;
  border-color: var(--sage);
  border-width: 2px;
  padding: 11px 13px;
}
.field textarea:focus { padding: 11px 13px; }

.contact-form .btn-primary {
  width: 100%;
  margin-top: 24px;
  height: 52px;
  border-radius: 8px;
}

/* Reassurance card */
.reassure-card {
  background: var(--dew);
  border-radius: var(--radius-lg);
  padding: 32px;
  border-left: 3px solid var(--sage);
}

.reassure-card__intro {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}
.reassure-card__intro svg {
  width: 18px;
  height: 18px;
  color: var(--sage);
  flex: 0 0 auto;
  margin-top: 4px;
}
.reassure-card__intro p {
  font-size: 15px;
  color: var(--slate);
  line-height: 1.7;
}

.trust-list {
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.trust-list li {
  display: flex;
  gap: 10px;
  font-size: 14px;
  color: var(--stone);
  line-height: 1.5;
  align-items: flex-start;
}
.trust-list svg {
  width: 16px;
  height: 16px;
  color: var(--sage);
  flex: 0 0 auto;
  margin-top: 2px;
}

.callback-line {
  margin-top: 20px;
  font-style: italic;
  font-size: 14px;
  color: var(--stone);
}
.callback-line .number { color: var(--sage); font-weight: 600; font-style: normal; }

@media (max-width: 1024px) {
  .contact-form-grid { grid-template-columns: 1fr; }
}
@media (max-width: 540px) {
  .field-grid { grid-template-columns: 1fr; }
  .field-grid .field--full { grid-column: auto; }
}

/* ==========================================================================
   Map block
   ========================================================================== */
.map-section { background: var(--mist); }

.map-grid {
  display: grid;
  grid-template-columns: 55% 45%;
  gap: 48px;
  align-items: stretch;
}

.map-tile {
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: 0 4px 20px rgba(26,35,50,0.08);
  border: 1px solid var(--mist);
  background: var(--white);
  aspect-ratio: 4/3;
}
.map-tile svg { width: 100%; height: 100%; display: block; }

.map-info { display: flex; flex-direction: column; justify-content: center; }
.map-info .body-copy {
  margin-top: 20px;
  font-size: 15px;
  color: var(--slate);
  line-height: 1.7;
}
.map-info .body-copy strong { font-weight: 600; }

.map-info-list {
  margin-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.map-info-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: var(--stone);
  line-height: 1.5;
}
.map-info-list svg {
  width: 16px;
  height: 16px;
  color: var(--sage);
  flex: 0 0 auto;
}

@media (max-width: 1024px) {
  .map-grid { grid-template-columns: 1fr; }
}

/* ==========================================================================
   Contact channels (feature_grid)
   ========================================================================== */
.contact-channels { background: var(--white); padding: 72px 0; }

.contact-channels__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-top: 32px;
}

.channel-card {
  background: var(--dew);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  transition: background-color 200ms ease;
}
.channel-card:hover { background: #C7E7DD; }

.channel-card__icon {
  width: 32px;
  height: 32px;
  color: var(--sage);
  margin-bottom: 12px;
}
.channel-card h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 16px;
  letter-spacing: -0.01em;
  color: var(--slate);
  margin-bottom: 8px;
}
.channel-card p {
  font-size: 14px;
  color: var(--stone);
  line-height: 1.65;
}
.channel-card .accent { color: var(--sage); font-weight: 600; }

@media (max-width: 1024px) {
  .contact-channels__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 540px) {
  .contact-channels__grid { grid-template-columns: 1fr; }
}

/* ==========================================================================
   Contact FAQ split
   ========================================================================== */
.contact-faq { background: var(--cloud); }

.contact-faq__grid {
  display: grid;
  grid-template-columns: 55% 45%;
  gap: 48px;
  align-items: start;
}

.contact-faq__list { order: 1; }
.contact-faq__sidebar { order: 2; }

.contact-faq__sidebar h2 {
  margin-top: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 28px;
  color: var(--slate);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.contact-illo-tile {
  background: var(--mist);
  border-radius: var(--radius-xl);
  padding: 24px;
  width: 100%;
  max-width: 320px;
  margin: 28px 0 24px;
  aspect-ratio: 4/3;
}
.contact-illo-tile svg { width: 100%; height: 100%; }

.contact-faq__footer-line {
  margin-top: 40px;
  text-align: center;
  font-style: italic;
  font-size: 14px;
  color: var(--stone);
}
.contact-faq__footer-line .number { color: var(--sage); font-style: normal; }

@media (max-width: 1024px) {
  .contact-faq__grid { grid-template-columns: 1fr; }
  .contact-faq__sidebar { order: 1; }
  .contact-faq__list { order: 2; }
}

/* ==========================================================================
   Helpers
   ========================================================================== */
.text-left { text-align: left; }
.text-center { text-align: center; }
.mt-32 { margin-top: 32px; }
.mt-40 { margin-top: 40px; }

.center-cta {
  margin-top: 40px;
  display: flex;
  justify-content: center;
}
